const menu=document.querySelector('.menu'),nav=document.querySelector('#nav');menu.addEventListener('click',()=>{const open=nav.classList.toggle('open');menu.setAttribute('aria-expanded',open);menu.setAttribute('aria-label',open?'Close navigation':'Open navigation')});nav.querySelectorAll('a').forEach(a=>a.addEventListener('click',()=>{nav.classList.remove('open');menu.setAttribute('aria-expanded','false');menu.setAttribute('aria-label','Open navigation')}));
const quotes=[...document.querySelectorAll('.quote')],dots=[...document.querySelectorAll('.dots button')];dots.forEach((dot,i)=>dot.addEventListener('click',()=>{quotes.forEach((q,j)=>q.classList.toggle('active',i===j));dots.forEach((d,j)=>d.classList.toggle('active',i===j))}));
const bookingForm=document.querySelector('#booking-form'),dateField=document.querySelector('#date'),bookingReview=bookingForm.querySelector('.booking-review'),reviewText=bookingReview.querySelector('pre'),reviewSend=bookingReview.querySelector('[data-review-send]');dateField.min=new Date().toISOString().slice(0,10);
document.querySelectorAll('[data-booking-service]').forEach(link=>link.addEventListener('click',()=>{bookingForm.elements.service.value=link.dataset.bookingService;if(link.dataset.bookingPickup)bookingForm.elements.pickup.value=link.dataset.bookingPickup;if(link.dataset.bookingNotes)bookingForm.elements.message.value=link.dataset.bookingNotes}));
bookingForm.addEventListener('submit',e=>{e.preventDefault();const f=new FormData(bookingForm);const msg=`Hello Zeelie Taxis, I would like to request a quotation.\n\nService: ${f.get('service')}\nName: ${f.get('name')}\nContact: ${f.get('contact')}\nPickup: ${f.get('pickup')}\nDestination: ${f.get('destination')}\nDate: ${f.get('date')}\nPickup time: ${f.get('time')||'Not specified'}\nPassengers: ${f.get('passengers')}\nFlight: ${f.get('flight')||'Not applicable'}\nLuggage / equipment: ${f.get('luggage')||'Not specified'}\nReturn: ${f.get('return')}\nNotes: ${f.get('message')||'None'}`;reviewText.textContent=msg.replace('Hello Zeelie Taxis, I would like to request a quotation.\n\n','');reviewSend.href=`https://wa.me/27825557441?text=${encodeURIComponent(msg)}`;bookingReview.hidden=false;bookingReview.scrollIntoView({behavior:'smooth',block:'nearest'})});bookingForm.querySelector('[data-review-edit]').addEventListener('click',()=>{bookingReview.hidden=true;bookingForm.elements.service.focus()});
document.querySelector('#year').textContent=new Date().getFullYear();
const gallery=document.querySelector('.gallery-track'),gallerySlides=[...gallery.querySelectorAll('figure')],galleryCurrent=document.querySelector('#gallery-current');
const galleryStep=()=>gallerySlides[0].getBoundingClientRect().width+16;
let galleryPaused=false,galleryManualPause=false,galleryAuto;const galleryPause=document.querySelector('[data-gallery-pause]');
const moveGallery=direction=>{const current=Math.round(gallery.scrollLeft/galleryStep()),visible=window.innerWidth<=900?1:2,max=Math.max(0,gallerySlides.length-visible),next=direction>0?(current>=max?0:current+1):(current<=0?max:current-1);gallery.scrollTo({left:next*galleryStep(),behavior:'smooth'})};
const restartGallery=()=>{clearInterval(galleryAuto);if(!galleryManualPause&&!window.matchMedia('(prefers-reduced-motion: reduce)').matches)galleryAuto=setInterval(()=>{if(!galleryPaused&&!document.hidden)moveGallery(1)},6000)};
document.querySelector('[data-gallery-prev]').addEventListener('click',()=>{moveGallery(-1);restartGallery()});
document.querySelector('[data-gallery-next]').addEventListener('click',()=>{moveGallery(1);restartGallery()});
gallery.addEventListener('scroll',()=>{const active=Math.max(0,Math.min(gallerySlides.length-1,Math.round(gallery.scrollLeft/galleryStep())));galleryCurrent.textContent=String(active+1).padStart(2,'0')},{passive:true});
gallery.addEventListener('mouseenter',()=>galleryPaused=true);gallery.addEventListener('mouseleave',()=>galleryPaused=false);gallery.addEventListener('focusin',()=>galleryPaused=true);gallery.addEventListener('focusout',()=>galleryPaused=false);restartGallery();
galleryPause.addEventListener('click',()=>{galleryManualPause=!galleryManualPause;galleryPause.setAttribute('aria-pressed',galleryManualPause);galleryPause.setAttribute('aria-label',galleryManualPause?'Play journey gallery':'Pause journey gallery');galleryPause.textContent=galleryManualPause?'▶':'Ⅱ';restartGallery()});
const serviceTrack=document.querySelector('.service-track'),serviceSlides=[...serviceTrack.querySelectorAll('.service')],serviceCurrent=document.querySelector('#service-current');
const serviceStep=()=>serviceSlides[0].getBoundingClientRect().width+2;let servicePaused=false,serviceManualPause=false,serviceAuto;const servicePause=document.querySelector('[data-service-pause]');
const moveServices=direction=>{const current=Math.round(serviceTrack.scrollLeft/serviceStep()),visible=window.innerWidth<=900?1:2,max=Math.max(0,serviceSlides.length-visible),next=direction>0?(current>=max?0:current+1):(current<=0?max:current-1);serviceTrack.scrollTo({left:next*serviceStep(),behavior:'smooth'})};
const restartServices=()=>{clearInterval(serviceAuto);if(!serviceManualPause&&!window.matchMedia('(prefers-reduced-motion: reduce)').matches)serviceAuto=setInterval(()=>{if(!servicePaused&&!document.hidden)moveServices(1)},6500)};
document.querySelector('[data-service-prev]').addEventListener('click',()=>{moveServices(-1);restartServices()});document.querySelector('[data-service-next]').addEventListener('click',()=>{moveServices(1);restartServices()});
serviceTrack.addEventListener('scroll',()=>{const active=Math.max(0,Math.min(serviceSlides.length-1,Math.round(serviceTrack.scrollLeft/serviceStep())));serviceCurrent.textContent=String(active+1).padStart(2,'0')},{passive:true});serviceTrack.addEventListener('mouseenter',()=>servicePaused=true);serviceTrack.addEventListener('mouseleave',()=>servicePaused=false);serviceTrack.addEventListener('focusin',()=>servicePaused=true);serviceTrack.addEventListener('focusout',()=>servicePaused=false);restartServices();
servicePause.addEventListener('click',()=>{serviceManualPause=!serviceManualPause;servicePause.setAttribute('aria-pressed',serviceManualPause);servicePause.setAttribute('aria-label',serviceManualPause?'Play services carousel':'Pause services carousel');servicePause.textContent=serviceManualPause?'▶':'Ⅱ';restartServices()});
const backToTop=document.querySelector('.back-to-top');const toggleBackToTop=()=>backToTop.classList.toggle('show',window.scrollY>700);window.addEventListener('scroll',toggleBackToTop,{passive:true});toggleBackToTop();backToTop.addEventListener('click',()=>window.scrollTo({top:0,behavior:'smooth'}));
